.poutine-card {
  list-style: none;
}

.poutine-card__button {
  display: flex;
  align-items: stretch;
  gap: var(--space-md);
  width: 100%;
  text-align: left;
  background-color: var(--color-paper-white);
  border: 2px solid var(--color-gravy-ink);
  border-radius: var(--radius-md);
  box-shadow: var(--shadow-sticker);
  padding: var(--space-md);
  transition: box-shadow 0.1s ease;
}

.poutine-card__button:hover {
  box-shadow: var(--shadow-sticker-lifted);
}

.poutine-card__button:active {
  box-shadow: var(--shadow-sticker-pressed);
}

.poutine-card__photo-wrap {
  flex-shrink: 0;
  width: 88px;
  height: 88px;
}

.poutine-card__photo {
  width: 88px;
  height: 88px;
  object-fit: cover;
  border-radius: var(--radius-sm);
  border: 2px solid var(--color-gravy-ink);
}

.poutine-card__photo--placeholder {
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 2rem;
  background-color: var(--color-cream-counter);
}

.poutine-card__body {
  display: flex;
  flex-direction: column;
  gap: var(--space-xs);
  min-width: 0;
}

.poutine-card__title {
  font-family: var(--font-body);
